using System;using System.Collections.Generic;using Beast.Claw.Attributes;using Beast.Claw.Reflection;using Unity.Mathematics;using UnityEngine;namespace Beast.Claw.Common{    [DomainInitialize]    public static class BDebug    {        public static IReadOnlyDictionary<string, DebugTrackStorage> TrackStorages => _trackStorages;                private static readonly Dictionary<string, DebugTrackStorage> _trackStorages;        static BDebug()        {            try            {                _trackStorages = new Dictionary<string, DebugTrackStorage>();            }            catch (Exception e)            {                _LogException(e);            }        }        public static void ClearTrackStorage()        {            _trackStorages.Clear();        }                public static void Track<T>(T owner, string id, int value)        {            _GetOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, float value)        {            _GetOrCreateStorage(owner).Write(id, value);        }        public static void Track<T>(T owner, string id, float2 value)        {            _GetOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, float3 value)        {            _GetOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, float4 value)        {            _GetOrCreateStorage(owner).Write(id, value);        }                public static void Track<T>(T owner, string id, string value)        {            _GetOrCreateStorage(owner).Write(id, value);        }                public static void LogInfo<T>(T owner, string message)        {            _LogInfo(TypeStorage<T>.FullName + ": " + message);        }                public static void LogError<T>(T owner, string message)        {            _LogError(TypeStorage<T>.FullName + ": " + message);        }                public static void LogStaticError(string message)        {            _LogError(message);        }        public static void LogException<T>(T owner, Exception e, string message)        {            _LogError(TypeStorage<T>.FullName + ": " + message);            _LogException(e);        }        public static void LogStaticException(Exception e, string message)        {            _LogError(message);            _LogException(e);        }        private static void _LogInfo(string message)        {            Debug.Log(message);        }                private static void _LogError(string message)        {            Debug.LogError(message);        }        private static void _LogException(Exception e)        {            Debug.LogException(e);        }        private static DebugTrackStorage _GetOrCreateStorage<TOwner>(TOwner owner)        {            string name = TypeStorage<TOwner>.FullName;            return _trackStorages.GetOrCreate(name);        }    }}